/* keyboard shortcut walk-through. rows: [name, keys[], caption] */
function kShort(title,rows,o={}){
 return DEMO(()=>`<div class="dkkbs">${dkHead(title,o.sub)}<div class="dkkl" data-k="lab"></div>${kb({noFn:true})}</div>`,
  [C(o.start||'Watch the keys light up. Hold the first key, then tap the next one.'),...rows.flatMap(([n,k,c])=>[['set','lab',`<b>${n}</b>`,0],kk(k,1700),C(c||n)])],
  {cls:'plain',noCursor:true,intro:KINTRO,alt:title});
}
/* pie chart drawn from values */
function pieSVG(vals,cols){const t=vals.reduce((a,b)=>a+b,0);let a=-Math.PI/2;return `<svg viewBox="-1.1 -1.1 2.2 2.2">${vals.map((v,i)=>{const b=a+v/t*2*Math.PI;const d=`M0 0 L${Math.cos(a)} ${Math.sin(a)} A1 1 0 ${b-a>Math.PI?1:0} 1 ${Math.cos(b)} ${Math.sin(b)}Z`;a=b;return `<path d="${d}" fill="${cols[i]}" stroke="#fff" stroke-width=".02"/>`}).join('')}</svg>`}
/* keys that differ on Mac and Windows: resolved when the demo plays */
const kk=(keys,ms=1300)=>['fn',async p=>p.x(['keys',keys.map(k=>P(k)).filter(Boolean),ms],()=>true)];
const typeKeys=(s,ms=330)=>['press',s.split('').map(c=>c===' '?'space':c),'paper',ms];

